1 | /**
2 |  * 主入口文件
3 |  * 初始化并启动 AI Agent 应用
4 |  */
5 | import dotenv from 'dotenv';
6 | import { OpenAIProvider } from './providers/openai';
7 | import Agent from './agent';
8 | import { CLI } from './cli';
9 | import { registerDefaultToolsAsync, ToolRegistry } from './tool';
10 | import { SessionManager } from './session-v2';
11 | import { operatorPrompt } from './prompts/operator';
12 | import path from 'path';
13 | import fs from 'fs';
14 | 
15 | const env = process.env.NODE_ENV || 'development';
16 | dotenv.config({ path: `.env.${env}`, override: true });
17 | 
18 | /**
19 |  * 应用配置
20 |  */
21 | interface AppConfig {
22 |     deepseekApiKey: string;
23 |     deepseekBaseUrl: string;
24 | }
25 | 
26 | /**
27 |  * 初始化应用
28 |  */
29 | async function initializeApp(config: AppConfig) {
30 |     // 1. 连接数据库
31 |     // await connectDB();
32 | 
33 |     // 2. 初始化工具（包括 MCP 工具）
34 |     await registerDefaultToolsAsync();
35 | 
36 |  
37 |     // 5. 初始化 LLM Provider
38 |     const llmProvider = new OpenAIProvider({
39 |         apiKey: config.deepseekApiKey,
40 |         baseURL: config.deepseekBaseUrl,
41 |     });
42 |       
43 | 
44 |    const sessionManager = new SessionManager({
45 |        sessionId:new Date().getTime().toString(),
46 |        llmProvider,
47 |    });
48 |    
49 |   await sessionManager.init();
50 | 
51 |     ToolRegistry.setContext({
52 |         sessionId: sessionManager.id,
53 |         sessionPath: sessionManager.sessionPath,
54 |     });
55 | 
56 | 
57 |     const customPrompt = operatorPrompt({
58 |         directory: process.cwd(),
59 |         vcs: "git",
60 |     });
61 | 
62 |     console.log(`Available tools:\n${ToolRegistry.getSchemas().map(tool => `'${tool.function.name}'`).join("\n")}`);
63 | 
64 |     fs.writeFileSync(path.resolve(process.cwd(), 'customPrompt.md'), customPrompt);
65 |     const agent = new Agent({
66 |         llmProvider,
67 |         sessionManager,
68 |         systemPrompt: customPrompt,
69 |         defaultTools: ToolRegistry.getSchemas(),
70 |     });
71 | 
72 |     return { agent, sessionManager };
73 | }
74 | 
75 | /**
76 |  * 启动 CLI 交互模式
77 |  */
78 | async function startCLI(agent: Agent, sessionManager: SessionManager): Promise<void> {
79 |     const cli = new CLI({
80 |         agent,
81 |         sessionManager,
82 |         sessionId: sessionManager.id,
83 |         prompt: '>',
84 |     });
85 | 
86 |     await cli.start();
87 | }
