1 | /**
2 |  * CLI - 交互式命令行界面
3 |  * 使用 prompts 库实现稳定的交互
4 |  */
5 | import { execSync } from 'node:child_process';
6 | import { ScopedLogger } from '../util/log';
7 | import Agent from '../agent';
8 | import { SessionManager } from '../session-v2';
9 | import { executeCommand } from './commands';
10 | import {  InputHistory } from './utils';
11 | import { readWithHistory } from './utils/reader';
12 | import type { CommandContext } from './commands/types';
13 | 
14 | export interface CLIConfig {
15 |     agent: Agent;
16 |     sessionManager: SessionManager;
17 |     sessionId?: string;
18 |     prompt?: string;
19 | }
20 | 
21 | export class CLI {
22 |     private agent: Agent;
23 |     private sessionManager: SessionManager;
24 |     private sessionId: { value: string };
25 |     private promptText: string;
26 |     private running: boolean;
27 |     private logger: ScopedLogger;
28 |     private inputHistory: InputHistory;
29 | 
30 |     constructor(config: CLIConfig) {
31 |         this.agent = config.agent;
32 |         this.sessionManager = config.sessionManager;
33 |         this.sessionId = { value: config.sessionId || 'session_10001' };
34 |         this.promptText = config.prompt || 'You';
35 |         this.running = false;
36 |         this.logger = new ScopedLogger('CLI');
37 |         this.inputHistory = new InputHistory();
38 |     }
39 | 
40 |     /**
41 |      * 启动 CLI
42 |      */
43 |     async start(): Promise<void> {
44 |         this.running = true;
45 | 
46 |         if (process.platform === 'win32') {
47 |             try {
48 |                 execSync('chcp 65001>nul');
49 |             } catch (_error) {
50 |                 // 忽略失败并保持默认代码页。
51 |             }
52 |         }
53 |         this.printWelcome();
54 | 
55 |         while (this.running) {
56 |             try {
57 |                 const input = await this.getInput();
58 | 
59 |                 const trimmed = input.trim();
60 |                 if (!trimmed) continue;
61 | 
62 |                 await this.handleInput(trimmed);
63 | 
64 |             } catch (error) {
65 |                 if (error instanceof Error && error.message === 'user cancelled') {
66 |                     this.shutdown();
67 |                     break;
68 |                 }
69 |                 console.error('\n❌ Error:', error);
70 |             }
71 |         }
72 |     }
73 | 
74 |     /**
75 |      * 获取用户输入（支持历史记录）
76 |      */
77 |     private async getInput(): Promise<string> {
78 |         const result = await readWithHistory(this.promptText, this.inputHistory);
79 |         // 更新历史记录引用
80 |         this.inputHistory = result.history;
81 |         return result.value;
82 |     }
83 | 
84 |     /**
85 |      * 处理用户输入
86 |      */
87 |     private async handleInput(input: string): Promise<void> {
88 |         const context: CommandContext = {
89 |             agent: this.agent,
90 |             running: { value: this.running },
91 |             sessionId: this.sessionId,
92 |             sessionManager: this.sessionManager,
93 |         };
94 | 
95 |         const isCommand = await executeCommand(input, context);
96 | 
97 |         // 更新运行状态
98 |         this.running = context.running.value;
99 | 
100 |         if (!isCommand) {
101 |             await this.handleChat(input);
102 |         }
103 |     }
104 | 
105 |     /**
106 |      * 处理对话输入（带加载动画）
107 |      */
108 |     private async handleChat(input: string): Promise<void> {
