226 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
227 |         const typeName = def?.typeName;
228 | 
229 |         switch (typeName) {
230 |             case 'ZodString':
231 |                 return { type: 'string' };
232 | 
233 |             case 'ZodNumber':
234 |                 return { type: 'number' };
235 | 
236 |             case 'ZodBoolean':
237 |                 return { type: 'boolean' };
238 | 
239 |             case 'ZodNull':
240 |                 return { type: 'null' };
241 | 
242 |             case 'ZodArray':
243 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
244 |                 return {
245 |                     type: 'array',
246 |                     items: itemType,
247 |                 };
248 | 
249 |             case 'ZodObject':
250 |                 return this.zodToJsonSchema({ _def: def });
251 | 
252 |             case 'ZodOptional':
253 |             case 'ZodNullable':
254 |             case 'ZodDefault':
255 |                 // innerType 是 Zod 对象，需要获取其 _def
256 |                 const wrappedType = def.innerType || def.schema || def.type;
257 |                 if (!wrappedType) {
258 |                     console.warn(`Missing wrapped type for field: ${key}, def:`, def);
259 |                     return {};
260 |                 }
261 |                 return this.zodTypeToJsonSchema(wrappedType._def || wrappedType, key);
262 | 
263 |             case 'ZodEnum':
264 |                 return {
265 |                     type: 'string',
266 |                     enum: def.values,
267 |                 };
268 | 
269 |             case 'ZodLiteral':
270 |                 return {
271 |                     type: typeof def.value,
272 |                     const: def.value,
273 |                 };
274 | 
275 |             case 'ZodUnion':
276 |             case 'ZodDiscriminatedUnion':
277 |                 return {
278 |                     anyOf: def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt)),
279 |                 };
280 | 
281 |             case 'ZodEffects':
282 |                 // 处理带描述的字段
283 |                 const effectType = def.innerType || def.schema || def.type;
284 |                 if (!effectType) {
285 |                     console.warn(`Missing effect inner type for field: ${key}, def:`, def);
286 |                     return {};
287 |                 }
288 |                 const innerSchema = this.zodTypeToJsonSchema(effectType._def || effectType, key);
289 |                 if (def.description) {
290 |                     return { ...innerSchema, description: def.description };
291 |                 }
292 |                 return innerSchema;
293 | 
294 |             default:
295 |                 // 未知类型，使用 any
296 |                 if (typeName !== undefined) {
297 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
298 |                 } else {
299 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
300 |                 }
301 |                 return {};
302 |         }
303 |     }
