16 | export interface EventContext<T = any> {
17 |   event: string;
18 |   data: T;
19 |   metadata: EventMetadata;
20 |   abort: () => void;
21 |   isAborted: boolean;
22 | }
23 | 
24 | export interface Middleware<T = any> {
25 |   (context: EventContext<T>, next: () => Promise<void>): Promise<void>;
26 | }
27 | 
28 | export interface EventBusOptions {
29 |   maxListeners?: number;
30 |   enableAsync?: boolean;
31 |   defaultTimeout?: number;
